// --- Quote edge cases ---

#[test]
fn handles_empty_double_quoted_value() {
    let content = r#"KEY="""#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"".to_string()));
}

#[test]
fn handles_empty_single_quoted_value() {
    let content = "KEY=''";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"".to_string()));
}

#[test]
fn mismatched_quotes_are_not_stripped() {
    let content = r#"KEY="value'"#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&r#""value'"#.to_string()));
}

#[test]
fn mismatched_quotes_reversed_are_not_stripped() {
    let content = "KEY='value\"";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"'value\"".to_string()));
}

#[test]
fn single_double_quote_is_preserved() {
    let content = r#"KEY=""#;
    let vars = EnvFileParser::parse(content).unwrap();
    // Single quote char: starts and ends with `"`, but len < 2
    assert_eq!(vars.get("KEY"), Some(&"\"".to_string()));
}

#[test]
fn single_single_quote_is_preserved() {
    let content = "KEY='";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"'".to_string()));
}

#[test]
fn opening_quote_without_closing_is_preserved() {
    let content = r#"KEY="no closing quote"#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"\"no closing quote".to_string()));
}

#[test]
fn single_quotes_inside_double_quotes() {
    let content = r#"KEY="it's a value""#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"it's a value".to_string()));
}

#[test]
fn double_quotes_inside_single_quotes() {
    let content = r#"KEY='he said "hi"'"#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&r#"he said "hi""#.to_string()));
}

#[test]
fn quotes_in_middle_of_value_are_kept() {
    let content = r#"KEY=val"ue"#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"val\"ue".to_string()));
}

#[test]
fn space_before_quoted_value_prevents_unquoting() {
    // After trimming ` "quoted"` becomes `"quoted"`, which gets unquoted
    let content = r#"KEY= "quoted""#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"quoted".to_string()));
}

// --- Escaped characters (parser does NOT interpret escapes) ---

#[test]
fn backslash_escaped_quotes_are_not_interpreted() {
    // The parser strips outer quotes but does not process escape sequences
    let content = r#"KEY="escaped \"quotes\"""#;
    let vars = EnvFileParser::parse(content).unwrap();
    // Outer " and last " are stripped; backslashes remain literal
    assert_eq!(
        vars.get("KEY"),
        Some(&r#"escaped \"quotes\"#.to_string())
    );
}

#[test]
fn backslash_n_is_literal() {
    let content = r#"KEY="line1\nline2""#;
    let vars = EnvFileParser::parse(content).unwrap();
    // \n is NOT converted to a newline — it stays as literal characters
    assert_eq!(vars.get("KEY"), Some(&r#"line1\nline2"#.to_string()));
}

#[test]
fn backslashes_are_literal() {
    let content = r#"KEY="path\\to\\file""#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&r#"path\\to\\file"#.to_string()));
}

// --- Key edge cases ---

#[test]
fn empty_key_from_leading_equals() {
    let content = "=value";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get(""), Some(&"value".to_string()));
}

#[test]
fn key_with_underscores_and_numbers() {
    let content = "MY_VAR_2=hello";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("MY_VAR_2"), Some(&"hello".to_string()));
}

#[test]
fn export_prefix_is_included_in_key() {
    // Unlike some .env parsers, this one does NOT strip `export `
    let content = "export KEY=value";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("export KEY"), Some(&"value".to_string()));
    assert_eq!(vars.get("KEY"), None);
}

// --- Whitespace edge cases ---

#[test]
fn whitespace_only_lines_are_skipped() {
    let content = "KEY1=a\n   \n\t\nKEY2=b";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.len(), 2);
}

#[test]
fn leading_and_trailing_whitespace_on_lines() {
    let content = "  KEY=value  ";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
}

#[test]
fn tabs_around_equals() {
    let content = "KEY\t=\tvalue";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
}

#[test]
fn whitespace_inside_quotes_is_preserved() {
    let content = r#"KEY="  spaces  ""#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"  spaces  ".to_string()));
}

// --- Comment edge cases ---

#[test]
fn inline_comment_is_included_in_value() {
    // This parser does NOT strip inline comments
    let content = "KEY=value # this is NOT stripped";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(
        vars.get("KEY"),
        Some(&"value # this is NOT stripped".to_string())
    );
}

#[test]
fn hash_in_quoted_value_is_preserved() {
    let content = r#"KEY="value#with#hashes""#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"value#with#hashes".to_string()));
}

#[test]
fn indented_comment_is_skipped() {
    let content = "  # indented comment\nKEY=value";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.len(), 1);
    assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
}

// --- Value edge cases ---

#[test]
fn value_with_multiple_equals_signs() {
    let content = "KEY=a=b=c=d";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"a=b=c=d".to_string()));
}

#[test]
fn duplicate_keys_last_wins() {
    let content = "KEY=first\nKEY=second";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"second".to_string()));
}

#[test]
fn unicode_in_values() {
    let content = "GREETING=こんにちは";
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("GREETING"), Some(&"こんにちは".to_string()));
}

#[test]
fn unicode_in_quoted_values() {
    let content = r#"KEY="café ☕""#;
    let vars = EnvFileParser::parse(content).unwrap();
    assert_eq!(vars.get("KEY"), Some(&"café ☕".to_string()));
}

#[test]
fn empty_content_returns_empty_map() {
    let vars = EnvFileParser::parse("").unwrap();
    assert!(vars.is_empty());
}

#[test]
fn only_comments_returns_empty_map() {
    let content = "# comment 1\n# comment 2\n";
    let vars = EnvFileParser::parse("").unwrap();
    assert!(vars.is_empty());
}

// --- File loading ---

#[test]
fn load_reads_from_file() {
    let dir = tempfile::TempDir::new().unwrap();
    let path = dir.path().join(".env");
    std::fs::write(&path, "FILE_KEY=file_value\n").unwrap();

    let vars = EnvFileParser::load(&path).unwrap();
    assert_eq!(vars.get("FILE_KEY"), Some(&"file_value".to_string()));
}

#[test]
fn load_returns_error_for_missing_file() {
    let result = EnvFileParser::load(Path::new("/nonexistent/.env"));
    assert!(result.is_err());
}

#[test]
fn load_optional_reads_existing_file() {
    let dir = tempfile::TempDir::new().unwrap();
    let path = dir.path().join(".env");
    std::fs::write(&path, "OPT_KEY=opt_value\n").unwrap();

    let vars = EnvFileParser::load_optional(&path).unwrap();
    assert_eq!(vars.get("OPT_KEY"), Some(&"opt_value".to_string()));
}

