//! .env file parsing.
//!
//! This module provides functionality for parsing environment variable files
//! in the standard KEY=value format.

use anyhow::Result;
use std::collections::HashMap;
use std::path::Path;

/// Parses .env files into a map of environment variables.
///
/// # Supported Formats
///
/// - Simple: `KEY=value`
/// - Quoted: `KEY="value with spaces"` or `KEY='single quoted'`
/// - Empty: `KEY=`
/// - Comments: `# This is a comment`
/// - Whitespace around equals: `KEY = value`
/// - Values with equals signs: `URL=https://example.com?foo=bar`
///
/// # Example
///
/// ```
/// use bivvy::config::EnvFileParser;
///
/// let content = r#"
/// # Database config
/// DATABASE_URL=postgres://localhost/db
/// DEBUG="true"
/// EMPTY=
/// "#;
///
/// let vars = EnvFileParser::parse(content).unwrap();
/// assert_eq!(vars.get("DATABASE_URL"), Some(&"postgres://localhost/db".to_string()));
/// assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
/// assert_eq!(vars.get("EMPTY"), Some(&"".to_string()));
/// ```
pub struct EnvFileParser;

impl EnvFileParser {
    /// Parse an env file content string into a map of variables.
    pub fn parse(content: &str) -> Result<HashMap<String, String>> {
        let mut vars = HashMap::new();

        for line in content.lines() {
            let line = line.trim();

            // Skip empty lines and comments
            if line.is_empty() || line.starts_with('#') {
                continue;
            }

            // Parse KEY=value
            if let Some((key, value)) = Self::parse_line(line) {
                vars.insert(key, value);
            }
        }

        Ok(vars)
    }

    /// Parse a single line.
    fn parse_line(line: &str) -> Option<(String, String)> {
        let eq_pos = line.find('=')?;
        let key = line[..eq_pos].trim().to_string();
        let value = line[eq_pos + 1..].trim();

        // Handle quoted values
        let value = Self::unquote(value);

        Some((key, value))
    }

    /// Remove surrounding quotes from a value.
    fn unquote(value: &str) -> String {
        if (value.starts_with('"') && value.ends_with('"'))
            || (value.starts_with('\'') && value.ends_with('\''))
        {
            if value.len() >= 2 {
                value[1..value.len() - 1].to_string()
            } else {
                value.to_string()
            }
        } else {
            value.to_string()
        }
    }

    /// Load and parse an env file from a path.
    ///
    /// # Example
    ///
    /// ```no_run
    /// use bivvy::config::EnvFileParser;
    /// use std::path::Path;
    ///
    /// let vars = EnvFileParser::load(Path::new(".env")).unwrap();
    /// for (key, value) in &vars {
    ///     println!("{}={}", key, value);
    /// }
    /// ```
    pub fn load(path: &Path) -> Result<HashMap<String, String>> {
        let content = std::fs::read_to_string(path)?;
        Self::parse(&content)
    }

    /// Load and parse an env file, returning empty map if file doesn't exist.
    pub fn load_optional(path: &Path) -> Result<HashMap<String, String>> {
        if path.exists() {
            Self::load(path)
        } else {
            Ok(HashMap::new())
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_simple_env_file() {
        let content = r#"
KEY1=value1
KEY2=value2
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("KEY1"), Some(&"value1".to_string()));
        assert_eq!(vars.get("KEY2"), Some(&"value2".to_string()));
    }

    #[test]
    fn skips_comments() {
        let content = r#"
# This is a comment
KEY=value
# Another comment
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.len(), 1);
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn handles_quoted_values() {
        let content = r#"
DOUBLE="double quoted"
SINGLE='single quoted'
UNQUOTED=no quotes
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("DOUBLE"), Some(&"double quoted".to_string()));
        assert_eq!(vars.get("SINGLE"), Some(&"single quoted".to_string()));
        assert_eq!(vars.get("UNQUOTED"), Some(&"no quotes".to_string()));
    }

    #[test]
    fn handles_empty_values() {
        let content = "EMPTY=";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("EMPTY"), Some(&"".to_string()));
    }

    #[test]
    fn handles_values_with_equals() {
        let content = "URL=https://example.com?foo=bar";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(
            vars.get("URL"),
            Some(&"https://example.com?foo=bar".to_string())
        );
    }

    #[test]
    fn handles_whitespace_around_equals() {
        let content = "KEY = value with spaces";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("KEY"), Some(&"value with spaces".to_string()));
    }

    #[test]
    fn skips_empty_lines() {
        let content = r#"
KEY1=value1

KEY2=value2

"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.len(), 2);
    }

    #[test]
    fn handles_lines_without_equals() {
        let content = r#"
KEY1=value1
invalid line without equals
KEY2=value2
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.len(), 2);
    }

    #[test]
    fn load_optional_returns_empty_for_missing_file() {
        let result = EnvFileParser::load_optional(Path::new("/nonexistent/path/.env"));

        assert!(result.is_ok());
        assert!(result.unwrap().is_empty());
    }

    // --- Quote edge cases ---

    #[test]
    fn handles_empty_double_quoted_value() {
        let content = r#"KEY="""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn handles_empty_single_quoted_value() {
        let content = "KEY=''";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn mismatched_quotes_are_not_stripped() {
        let content = r#"KEY="value'"#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#""value'"#.to_string()));
    }

    #[test]
    fn mismatched_quotes_reversed_are_not_stripped() {
        let content = "KEY='value\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'value\"".to_string()));
    }

    #[test]
    fn single_double_quote_is_preserved() {
        let content = r#"KEY=""#;
        let vars = EnvFileParser::parse(content).unwrap();
        // Single quote char: starts and ends with `"`, but len < 2
        assert_eq!(vars.get("KEY"), Some(&"\"".to_string()));
    }

    #[test]
    fn single_single_quote_is_preserved() {
        let content = "KEY='";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'".to_string()));
    }

    #[test]
    fn opening_quote_without_closing_is_preserved() {
        let content = r#"KEY="no closing quote"#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"\"no closing quote".to_string()));
    }

    #[test]
    fn single_quotes_inside_double_quotes() {
        let content = r#"KEY="it's a value""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"it's a value".to_string()));
    }

    #[test]
    fn double_quotes_inside_single_quotes() {
        let content = r#"KEY='he said "hi"'"#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"he said "hi""#.to_string()));
    }

    #[test]
    fn quotes_in_middle_of_value_are_kept() {
        let content = r#"KEY=val"ue"#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"val\"ue".to_string()));
    }

    #[test]
    fn space_before_quoted_value_prevents_unquoting() {
        // After trimming ` "quoted"` becomes `"quoted"`, which gets unquoted
        let content = r#"KEY= "quoted""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"quoted".to_string()));
    }

    // --- Escaped characters (parser does NOT interpret escapes) ---

    #[test]
    fn backslash_escaped_quotes_are_not_interpreted() {
        // The parser strips outer quotes but does not process escape sequences.
        // Input value after `=`: "escaped \"quotes\""
        // The unquote function sees the outermost " pair and strips them,
        // leaving the backslashes and inner quotes intact.
        let content = r#"KEY="escaped \"quotes\"""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&r#"escaped \"quotes\""#.to_string())
        );
    }

    #[test]
    fn backslash_n_is_literal() {
        let content = r#"KEY="line1\nline2""#;
        let vars = EnvFileParser::parse(content).unwrap();
        // \n is NOT converted to a newline — it stays as literal characters
        assert_eq!(vars.get("KEY"), Some(&r#"line1\nline2"#.to_string()));
    }

    #[test]
    fn backslashes_are_literal() {
        let content = r#"KEY="path\\to\\file""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"path\\to\\file"#.to_string()));
    }

    // --- Key edge cases ---

    #[test]
    fn empty_key_from_leading_equals() {
        let content = "=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get(""), Some(&"value".to_string()));
    }

    #[test]
    fn key_with_underscores_and_numbers() {
        let content = "MY_VAR_2=hello";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("MY_VAR_2"), Some(&"hello".to_string()));
    }

    #[test]
    fn export_prefix_is_included_in_key() {
        // Unlike some .env parsers, this one does NOT strip `export `
        let content = "export KEY=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("export KEY"), Some(&"value".to_string()));
        assert_eq!(vars.get("KEY"), None);
    }

    // --- Whitespace edge cases ---

    #[test]
    fn whitespace_only_lines_are_skipped() {
        let content = "KEY1=a\n   \n\t\nKEY2=b";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.len(), 2);
    }

    #[test]
    fn leading_and_trailing_whitespace_on_lines() {
        let content = "  KEY=value  ";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn tabs_around_equals() {
        let content = "KEY\t=\tvalue";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn whitespace_inside_quotes_is_preserved() {
        let content = r#"KEY="  spaces  ""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"  spaces  ".to_string()));
    }

    // --- Comment edge cases ---

    #[test]
    fn inline_comment_is_included_in_value() {
        // This parser does NOT strip inline comments
        let content = "KEY=value # this is NOT stripped";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # this is NOT stripped".to_string())
        );
    }

    #[test]
    fn hash_in_quoted_value_is_preserved() {
        let content = r#"KEY="value#with#hashes""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value#with#hashes".to_string()));
    }

    #[test]
    fn indented_comment_is_skipped() {
        let content = "  # indented comment\nKEY=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.len(), 1);
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    // --- Value edge cases ---

    #[test]
    fn value_with_multiple_equals_signs() {
        let content = "KEY=a=b=c=d";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"a=b=c=d".to_string()));
    }

    #[test]
    fn duplicate_keys_last_wins() {
        let content = "KEY=first\nKEY=second";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"second".to_string()));
    }

    #[test]
    fn unicode_in_values() {
        let content = "GREETING=こんにちは";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("GREETING"), Some(&"こんにちは".to_string()));
    }

    #[test]
    fn unicode_in_quoted_values() {
        let content = r#"KEY="café ☕""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"café ☕".to_string()));
    }

    #[test]
    fn empty_content_returns_empty_map() {
        let vars = EnvFileParser::parse("").unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn only_comments_returns_empty_map() {
        let content = "# comment 1\n# comment 2\n";
        let vars = EnvFileParser::parse("").unwrap();
        assert!(vars.is_empty());
    }

    // --- File loading ---

    #[test]
    fn load_reads_from_file() {
        let dir = tempfile::TempDir::new().unwrap();
        let path = dir.path().join(".env");
        std::fs::write(&path, "FILE_KEY=file_value\n").unwrap();

        let vars = EnvFileParser::load(&path).unwrap();
        assert_eq!(vars.get("FILE_KEY"), Some(&"file_value".to_string()));
    }

    #[test]
    fn load_returns_error_for_missing_file() {
        let result = EnvFileParser::load(Path::new("/nonexistent/.env"));
        assert!(result.is_err());
    }

    #[test]
    fn load_optional_reads_existing_file() {
        let dir = tempfile::TempDir::new().unwrap();
        let path = dir.path().join(".env");
        std::fs::write(&path, "OPT_KEY=opt_value\n").unwrap();

        let vars = EnvFileParser::load_optional(&path).unwrap();
        assert_eq!(vars.get("OPT_KEY"), Some(&"opt_value".to_string()));
    }

    #[test]
    fn complex_env_file() {
        let content = r#"
# Application settings
APP_NAME=MyApp
DEBUG=true

# Database
DATABASE_URL="postgres://user:pass@localhost:5432/db"

# API Keys
API_KEY='secret-key-123'
WEBHOOK_URL=https://api.example.com/webhook?token=abc&id=123
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("APP_NAME"), Some(&"MyApp".to_string()));
        assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
        assert_eq!(
            vars.get("DATABASE_URL"),
            Some(&"postgres://user:pass@localhost:5432/db".to_string())
        );
        assert_eq!(vars.get("API_KEY"), Some(&"secret-key-123".to_string()));
        assert!(vars.get("WEBHOOK_URL").unwrap().contains("token=abc"));
    }
}
